// indexInvoice adds an invoice to its organization's index, keeping the index oldest first. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoicesByOrg[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return invoiceBefore(inv, s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoicesByOrg[inv.OrgID] = ids
}

// invoiceBefore orders invoices oldest first, ties by ID.
func invoiceBefore(a, b Invoice) bool {
	if !a.CreatedAt.Equal(b.CreatedAt) {
		return a.CreatedAt.Before(b.CreatedAt)
	}
	return a.ID < b.ID
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	out, _ := s.ListInvoicesPage(orgID, f, time.Time{}, "", 0)
	return out
}

// ListInvoicesPage returns up to limit of an organization's invoices that match f, oldest first (ties by ID), starting after
// the invoice created at after with ID afterID. An empty afterID starts at the first invoice; a limit of 0 or less is no limit.
// more reports whether a matching invoice follows the page.
func (s *Store) ListInvoicesPage(orgID string, f InvoiceFilter, after time.Time, afterID string, limit int) (out []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoicesByOrg[orgID]
	start := 0
	if afterID != "" {
		start = sort.Search(len(ids), func(i int) bool { return cursorBefore(after, afterID, s.invoices[ids[i]]) })
	}
	out = []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		if limit > 0 && len(out) == limit {
			return out, true
		}
		out = append(out, copyInvoice(inv))
	}
	return out, false
}

// cursorBefore reports whether the position (t, id) comes before invoice inv in the order of invoiceBefore.
func cursorBefore(t time.Time, id string, inv Invoice) bool {
	if !t.Equal(inv.CreatedAt) {
		return t.Before(inv.CreatedAt)
	}
	return id < inv.ID
}

